const body = $json.body ?? $json;
const required = ['name', 'email', 'service', 'description'];
const missing = required.filter((key) => !String(body[key] ?? '').trim());
const email = String(body.email ?? '').trim().toLowerCase();
const emailLooksValid = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email);
const priority = /urgent|emergency|leak|unsafe|today/i.test(String(body.description ?? '')) ? 'high' : 'normal';
return [{ json: { accepted: missing.length === 0 && emailLooksValid, status: missing.length === 0 && emailLooksValid ? 'ready_for_human_review' : 'needs_correction', lead: { name: String(body.name ?? '').trim(), email, phone: String(body.phone ?? '').trim(), service: String(body.service ?? '').trim(), postcode: String(body.postcode ?? '').trim().toUpperCase(), description: String(body.description ?? '').trim(), priority }, validation: { missing_fields: missing, email_valid: emailLooksValid }, automation_policy: 'Draft and route only. Do not send customer messages or create quotes without contractor approval.' } }];
